def endpoint(base_url, path):
    # Normalize the base_url by stripping trailing slashes
    normalized_base = base_url.rstrip('/')

    # Check if the base_url already contains '/v1' at the end
    if normalized_base.endswith('/v1'):
        # If it does, we just append the path (stripped of leading slashes)
        return normalized_base + '/' + path.lstrip('/')
    elif normalized_base.endswith('/v1/'):
        # If it ends with '/v1/', we strip the trailing slash and append the path
        return normalized_base.rstrip('/') + '/' + path.lstrip('/')
    else:
        # If there's no '/v1' suffix, we append '/v1/' and the path
        return normalized_base + '/v1/' + path.lstrip('/')

